This finds the smallest missing positive integer in O(n) time and O(1) extra space. What does it print? Type the number.

```python
def first_missing(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

print(first_missing([3, 4, -1, 1]))
```

What does this spiral traversal print?

```python
def spiral(m):
    res = []
    top, bot, left, right = 0, len(m) - 1, 0, len(m[0]) - 1
    while top <= bot and left <= right:
        for j in range(left, right + 1): res.append(m[top][j])
        top += 1
        for i in range(top, bot + 1): res.append(m[i][right])
        right -= 1
        if top <= bot:
            for j in range(right, left - 1, -1): res.append(m[bot][j])
            bot -= 1
        if left <= right:
            for i in range(bot, top - 1, -1): res.append(m[i][left])
            left += 1
    return res

print(spiral([[1, 2, 3], [4, 5, 6], [7, 8, 9]]))
```

