def two_sum(nums, target):
    seen = {x: i for i, x in enumerate(nums)}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [i, seen[target - x]]

print(two_sum([3, 2, 4], 6), two_sum([3, 3], 6))
